/**
 * PikPakPublishRequest
 */
export type PikPakPublishRequest = {
    /**
     * Account Id
     *
     * 指定执行的 Userbot 账号 ID (可选)
     */
    account_id?: number | null;
    /**
     * Album Mode
     *
     * 相册模式 (默认关闭): 同文件夹批次内图片合成相册 photo 形态发送; 单文件超过分卷阈值不入组 (走占位卡/跳过); 整组失败全员 failed 零入库
     */
    album_mode?: boolean;
    /**
     * Auto Cleanup Mode
     *
     * 发布成功后网盘清理模式: none=保留原状; archive=移入已发布归档目录(默认); delete=移入回收站
     */
    auto_cleanup_mode?: 'none' | 'archive' | 'delete';
    /**
     * Dir Tree
     *
     * 目录树映射 {folder_id: rel_path} (用于结构化归档)
     */
    dir_tree?: {
        [key: string]: string;
    } | null;
    /**
     * Folder Name
     *
     * 文件夹标头名称 (用于频道总结卡等)
     */
    folder_name?: string | null;
    /**
     * Force Republish
     *
     * 强制重传: True 时忽略已发布防重记录重复发送 (刷屏/风控风险, 前端需确认警示); 发布历史照常写入保持幂等
     */
    force_republish?: boolean;
    /**
     * Is Folder Publish
     *
     * 是否为文件夹形态发布 (由前端根据是否含目录选择计算)
     */
    is_folder_publish?: boolean;
    /**
     * Oversize Policy
     *
     * 超限文件处理策略: skip_and_report=跳过并在总结中报告(默认); split=存档保真分卷; strict_fail=严格报错中断
     */
    oversize_policy?: 'skip_and_report' | 'split' | 'strict_fail';
    /**
     * Pikpak Prefetch Concurrency
     *
     * 预拉取并发通道数 (1-16, 推荐 6)
     */
    pikpak_prefetch_concurrency?: number | null;
    /**
     * Prefetch Concurrency
     *
     * 预拉取并发通道数别名 (1-16)
     */
    prefetch_concurrency?: number | null;
    /**
     * Priority
     *
     * 任务优先级 (数值越大优先级越高, 默认 10)
     */
    priority?: number | null;
    /**
     * Remote Files
     *
     * 远端文件快照列表 (file_id 必填主键; 服务端无 search/get-by-id, 快照为执行期元数据唯一自举途径)
     */
    remote_files: Array<PikPakFileItem>;
    /**
     * Send Delay Seconds
     *
     * 文件间发送风控延迟 (秒)
     */
    send_delay_seconds?: number;
    /**
     * Send Placeholder Card
     *
     * 是否在频道发送缺集占位说明卡 (skip_and_report 默认启用; 严禁写入 PublishHistory)
     */
    send_placeholder_card?: boolean;
    /**
     * Split Strategy
     *
     * 超限流式切片引擎策略
     */
    split_strategy?: 'vsse_with_fallback' | 'fmp4_universal' | 'raw' | null;
    /**
     * Target Channel
     *
     * 目标 Telegram 频道 ID/Username (必填)
     */
    target_channel: string;
    /**
     * Upload Concurrency
     *
     * 上传并发通道数 (1-16, 缺省 2=PIKPAK_UPLOAD_CONCURRENCY 稳健档)
     */
    upload_concurrency?: number | null;
    /**
     * Upload In Flight Per Connection
     *
     * 单连接在途分块数规范契约 (1-4, 缺省 1=PIKPAK_UPLOAD_IN_FLIGHT)
     */
    upload_in_flight_per_connection?: number | null;
};

